<?php
namespace App\Http\Controllers;
use App\Models\Partner; use App\Models\Unlock; use App\Models\UnlockParticipation; use App\Services\UnlockStatusService; use Illuminate\Http\Request; use Illuminate\Support\Str; use Inertia\Inertia;
class PartnerUnlockController extends Controller { private function authorize(Partner $partner,Request $r):void{abort_unless(in_array($r->user()->partners()->whereKey($partner->id)->firstOrFail()->pivot->role,['owner','manager'],true),403);} public function index(Request $r,Partner $partner){$this->authorize($partner,$r);return Inertia::render('partner/unlocks/index',['partner'=>$partner->only('name','slug'),'unlocks'=>Unlock::where('partner_id',$partner->id)->withCount(['participations as committed_count'=>fn($q)=>$q->where('status',UnlockParticipation::COMMITTED)])->latest()->get()]);} public function form(Request $r,Partner $partner,?Unlock $unlock=null){$this->authorize($partner,$r);if($unlock)abort_unless($unlock->partner_id===$partner->id,404);return Inertia::render('partner/unlocks/form',['partner'=>$partner->only('name','slug'),'unlock'=>$unlock,'locations'=>$partner->locations()->get(['id','name'])]);} public function save(Request $r,Partner $partner,?Unlock $unlock=null){$this->authorize($partner,$r);if($unlock)abort_unless($unlock->partner_id===$partner->id,404);$d=$r->validate(['title'=>'required|string|max:255','short_description'=>'nullable|string','description'=>'nullable|string','terms'=>'nullable|string','type'=>'required|in:BENEFIT,PRICE,EXPERIENCE,SECRET','minimum_commitments'=>'required|integer|min:1','maximum_capacity'=>'nullable|integer|min:1|gte:minimum_commitments','commitment_deadline'=>'nullable|date','free_user_offer'=>'nullable|string','member_offer'=>'nullable|string','location_ids'=>'array','location_ids.*'=>'exists:locations,id']);if($unlock?->participations()->where('status',UnlockParticipation::COMMITTED)->exists())abort(422,'No puedes modificar condiciones materiales después de compromisos.');$unlock??=new Unlock(['partner_id'=>$partner->id,'origin'=>'PARTNER','created_by_user_id'=>$r->user()->id,'status'=>Unlock::DRAFT]);$unlock->fill($d);$unlock->slug??=Str::slug($d['title']).'-'.Str::lower(Str::random(5));$unlock->save();$unlock->locations()->sync($d['location_ids']??[]);return to_route('partner.unlocks.index',$partner);} public function submit(Request $r,Partner $partner,Unlock $unlock,UnlockStatusService $s){$this->authorize($partner,$r);abort_unless($unlock->partner_id===$partner->id,404);$s->transition($unlock,Unlock::PENDING_REVIEW,$r->user(),null,[Unlock::DRAFT,Unlock::REJECTED]);return back();}}
